  select id into strict v_location from public.together_locations where world_id = v_world and slug = 'riverside-landing' and owner_user_id is null and archived_at is null;
  select id into strict v_primary from public.together_character_templates where slug = 'malcolm-reed' and published and creator_id is null;
  select id, repeat_identity, scheduling_rank, content_version, metadata into v_existing from public.together_world_pulse_templates where world_id = v_world and slug = 'river-reaches-the-steps';
  if found and (v_existing.repeat_identity <> 'juniper-city:major:river-reaches-the-steps' or v_existing.scheduling_rank <> 200 or v_existing.content_version > 1 or coalesce(v_existing.metadata->>'pulseTier', 'routine') <> 'major') then raise exception 'Unsafe Pulse identity, rank, tier or version edit: juniper-city/river-reaches-the-steps'; end if;
  v_facts := '[]'::jsonb;
  select coalesce(jsonb_agg(id::text order by id), '[]'::jsonb) into v_known_ids from public.together_character_templates where slug = any(array['malcolm-reed','naomi-chen','becka-shaw']::text[]) and published and creator_id is null;
  if jsonb_array_length(v_known_ids) <> 3 then raise exception 'Unknown Pulse fact knower: juniper-city/river-reaches-the-steps/public-report'; end if;
  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','After a night of rain, the river reaches Riverside Landing two hours earlier than the city forecast. The lower walk closes; a rescue boat finds a person stranded beneath the pedestrian span.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'river-reaches-the-steps','juniper-city:major:river-reaches-the-steps',200,1,'The River Reaches the Steps','After a night of rain, the river reaches Riverside Landing two hours earlier than the city forecast. The lower walk closes; a rescue boat finds a person stranded beneath the pedestrian span.','Juniper City treats the Riverwalk as an everyday route, not just a scenic path. After rain upstream, water reaches the lowest steps of Riverside Landing well ahead of the posted forecast. Mal Reed sends a rescue boat beneath the pedestrian span and brings one stranded cyclist ashore. Naomi Chen cancels a riverfront market before vendors carry their stock down to the landing. Becka Shaw compares the public gauge with a field reading and finds that the gauge is working; the forecast used an older upstream estimate.

The cyclist is safe and the upper path stays open. The lower route remains closed until a new crest reading comes in. City staff must explain why the earlier forecast persisted on public signs after the upstream number changed.','The cyclist is safe, but the posted forecast was late. What did each of you learn about the river?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['citywide','major-incident']::text[],'{"contentDigest":"77086a5585acd379dcc98ee7dc7e2ffc86e493f3edc9bbf5779f6069dda55b87","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
