  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,2,'Checked the gauge','The instrument was reading correctly. The stale input was in the forecast, which is a different problem and an important one.','Was the river gauge wrong?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from what you personally saw or verified. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_location from public.together_locations where world_id = v_world and slug = 'juniper-central-station' and owner_user_id is null and archived_at is null;
  select id into strict v_primary from public.together_character_templates where slug = 'noah-williams' and published and creator_id is null;
  select id, repeat_identity, scheduling_rank, content_version, metadata into v_existing from public.together_world_pulse_templates where world_id = v_world and slug = 'all-platforms-say-four';
  if found and (v_existing.repeat_identity <> 'juniper-city:major:all-platforms-say-four' or v_existing.scheduling_rank <> 201 or v_existing.content_version > 1 or coalesce(v_existing.metadata->>'pulseTier', 'routine') <> 'major') then raise exception 'Unsafe Pulse identity, rank, tier or version edit: juniper-city/all-platforms-say-four'; end if;
  v_facts := '[]'::jsonb;
  select coalesce(jsonb_agg(id::text order by id), '[]'::jsonb) into v_known_ids from public.together_character_templates where slug = any(array['noah-williams','jules-navarro','omar-haddad']::text[]) and published and creator_id is null;
  if jsonb_array_length(v_known_ids) <> 3 then raise exception 'Unknown Pulse fact knower: juniper-city/all-platforms-say-four/public-report'; end if;
  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','At the morning peak, Juniper Central Station boards send five different rail services to Platform Four. Dispatch holds departures while staff guide commuters using verified train numbers.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'all-platforms-say-four','juniper-city:major:all-platforms-say-four',201,1,'Every Platform Says Four','At the morning peak, Juniper Central Station boards send five different rail services to Platform Four. Dispatch holds departures while staff guide commuters using verified train numbers.','Thousands of Juniper residents use Central Station to cross the city. At the morning peak, every electronic platform board suddenly directs riders to Platform Four. Noah Williams stops boarding before the platform becomes unsafe. Jules Navarro uses the working radio circuit to read verified train numbers aloud, while Omar Haddad isolates a route-table update from the physical signal system. The trains are where the operators say they are; the public displays are wrong.

Service resumes with printed assignments and staff at each stair. The failed update has a valid maintenance signature but was published before its platform mapping passed a live check. Commuters still need to know which delayed connections are protected and who approved the premature release.','The trains were correctly routed while the boards were wrong. Who caught the difference first?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['citywide','major-incident']::text[],'{"contentDigest":"bb0556b69e89b65d4fa0949158e01a6d54bf560e174bdac4cbde70567ab87dae","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
