  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,0,'Stopped boarding','A delay was cheaper than letting a crowd follow a board onto one platform. I verified train positions before restarting service.','Were the trains actually headed to Platform Four?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from what you personally saw or verified. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'jules-navarro' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: juniper-city/all-platforms-say-four/jules-navarro'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,1,'Read the real assignments','The radio list was good, but people could barely hear it over the crowd. We needed staff on the stairs, not one louder announcement.','How did riders find the right train?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from what you personally saw or verified. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'omar-haddad' and published and creator_id is null;
