  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,2,'Isolated the display update','The signals and displays are separate. I found a signed route-table release, not proof of why somebody released it early.','What failed in the station system?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from what you personally saw or verified. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_location from public.together_locations where world_id = v_world and slug = 'civic-commons' and owner_user_id is null and archived_at is null;
  select id into strict v_primary from public.together_character_templates where slug = 'gabriel-ortiz' and published and creator_id is null;
  select id, repeat_identity, scheduling_rank, content_version, metadata into v_existing from public.together_world_pulse_templates where world_id = v_world and slug = 'the-bridge-stays-raised';
  if found and (v_existing.repeat_identity <> 'juniper-city:major:the-bridge-stays-raised' or v_existing.scheduling_rank <> 202 or v_existing.content_version > 1 or coalesce(v_existing.metadata->>'pulseTier', 'routine') <> 'major') then raise exception 'Unsafe Pulse identity, rank, tier or version edit: juniper-city/the-bridge-stays-raised'; end if;
  v_facts := '[]'::jsonb;
  select coalesce(jsonb_agg(id::text order by id), '[]'::jsonb) into v_known_ids from public.together_character_templates where slug = any(array['gabriel-ortiz','mateo-alvarez','amara-okafor']::text[]) and published and creator_id is null;
  if jsonb_array_length(v_known_ids) <> 3 then raise exception 'Unknown Pulse fact knower: juniper-city/the-bridge-stays-raised/public-report'; end if;
  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','A river crossing remains raised during the afternoon commute after its locking sensor gives two conflicting readings. Emergency vehicles divert and neighborhoods on both banks reorganize their evening.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-bridge-stays-raised','juniper-city:major:the-bridge-stays-raised',202,1,'The Bridge Stays Raised','A river crossing remains raised during the afternoon commute after its locking sensor gives two conflicting readings. Emergency vehicles divert and neighborhoods on both banks reorganize their evening.','Juniper City relies on its river crossings for work, school, and emergency travel. One movable span rises for a passing vessel and will not certify that it has locked after lowering. Gabriel Ortiz keeps traffic off it, and Mateo Alvarez redirects a fire crew to the longer crossing rather than testing the span with a heavy truck. Amara Okafor asks the city to publish the inspection order because nearby businesses are already being promised a reopening time nobody has verified.

Engineers find a misaligned sensor bracket and complete a physical lock test after sunset. The bridge reopens to light traffic first. The sensor fault is small, but the diversion exposed how few accessible crossings remain when one river route closes.','The bracket was fixed, but the detour changed more than one commute. What should the city learn?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['citywide','major-incident']::text[],'{"contentDigest":"a5cff2f56b211c1ba333e5494001c325e0dc33510653061ca3cd27d819773bb6","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
