  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,0,'Kept traffic off the span','The bridge looked level from the street. A lock reading still disagreed, so I would not open it on appearance.','Why did the bridge stay closed after it came down?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from what you personally saw or verified. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'mateo-alvarez' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: juniper-city/the-bridge-stays-raised/mateo-alvarez'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,1,'Rerouted a fire crew','We took the longer road. The delay mattered, but testing an uncertain bridge with a full engine would have added another emergency.','How did emergency crews get across the river?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from what you personally saw or verified. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'amara-okafor' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: juniper-city/the-bridge-stays-raised/amara-okafor'; end if;
  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,2,'Pressed for a public order','Businesses were quoting a reopening time the city had not certified. I wanted the actual inspection sequence on the record.','Who promised the bridge would reopen sooner?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from what you personally saw or verified. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_location from public.together_locations where world_id = v_world and slug = 'juniper-general-hospital' and owner_user_id is null and archived_at is null;
  select id into strict v_primary from public.together_character_templates where slug = 'priya-kapoor' and published and creator_id is null;
  select id, repeat_identity, scheduling_rank, content_version, metadata into v_existing from public.together_world_pulse_templates where world_id = v_world and slug = 'the-hospital-entrance-disappears';
  if found and (v_existing.repeat_identity <> 'juniper-city:major:the-hospital-entrance-disappears' or v_existing.scheduling_rank <> 203 or v_existing.content_version > 1 or coalesce(v_existing.metadata->>'pulseTier', 'routine') <> 'major') then raise exception 'Unsafe Pulse identity, rank, tier or version edit: juniper-city/the-hospital-entrance-disappears'; end if;
  v_facts := '[]'::jsonb;
  select coalesce(jsonb_agg(id::text order by id), '[]'::jsonb) into v_known_ids from public.together_character_templates where slug = any(array['priya-kapoor','talia-washington','jules-navarro']::text[]) and published and creator_id is null;
  if jsonb_array_length(v_known_ids) <> 3 then raise exception 'Unknown Pulse fact knower: juniper-city/the-hospital-entrance-disappears/public-report'; end if;
  v_facts := v_facts || jsonb_build_array(jsonb_build_object('id','public-report','text','A navigation update routes ambulances and rideshares to a closed service gate at Juniper General. Clinicians keep emergency intake open while the city corrects a widely shared map pin.','userVisible',true,'knownByCharacterTemplateIds',v_known_ids));
  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-hospital-entrance-disappears','juniper-city:major:the-hospital-entrance-disappears',203,1,'The Hospital Entrance Disappears from the Map','A navigation update routes ambulances and rideshares to a closed service gate at Juniper General. Clinicians keep emergency intake open while the city corrects a widely shared map pin.','An emergency entrance is useful only if people can find it. After an overnight navigation update, phones across Juniper point drivers toward a locked service gate at Juniper General Hospital. Priya Kapoor notices arriving patients have walked from the wrong side of the campus. Talia Washington posts staff at the open entrance and moves a portable registration desk nearer the street. Jules Navarro warns transit drivers, then checks that the corrected stop announcement is reaching the morning routes.

The hospital never closes emergency intake, and no ambulance loses a patient to the detour. The map provider accepts a correction, but cached directions persist on some phones. Staff keep the street team in place while the city works out who supplied the obsolete gate coordinates.','Emergency intake stayed open, yet people kept reaching the wrong gate. How was the route corrected?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['citywide','major-incident']::text[],'{"contentDigest":"97b13b341b876a4ad73055656d5168b865bd287a548ed20b807430938c881285","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
