  insert into public.together_world_pulse_template_participants (template_id,character_template_id,ordinal,role_label,perspective_summary,default_direct_message,knowledge) values (v_template,v_character,0,'Identified the wrong arrivals','Patients were reaching us, but by an unnecessary walk. I documented the route problem without discussing anyone’s treatment.','Was emergency care interrupted?','{"knownFactIds":["public-report"],"revealConstraints":["Speak from what you personally saw or verified. Do not claim another witness''s private reason."]}'::jsonb);
  select id into strict v_character from public.together_character_templates where slug = 'talia-washington' and published and creator_id is null;
  if not exists (select 1 from public.together_character_world_presence presence join public.together_character_versions version on version.id = presence.character_version_id join public.together_character_templates template on template.id = version.character_template_id and template.current_published_version = version.version where presence.world_id = v_world and presence.presence_type = 'resident' and template.id = v_character) then raise exception 'Nonresident Pulse participant: juniper-city/the-hospital-entrance-disappears/talia-washington'; end if;
