  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'heat-without-a-quiet-room','juniper-city:major:heat-without-a-quiet-room',204,1,'A Heat Advisory Without Enough Quiet Rooms','A severe heat advisory fills the city’s public cooling rooms. Staff open additional space, but one site that meets the temperature standard is inaccessible to residents using mobility aids.','Juniper’s hottest afternoon sends people from apartments, outdoor jobs, and delayed trains into public cooling rooms. Leila Rahman authorizes overflow space in Civic Commons. Reese Morgan checks the advertised sites and finds that a supposedly accessible room has a working lift but a heavy manual door at the final entrance. Hannah Mercin offers the school art room as a supervised daytime refuge once the building team confirms its cooling capacity.

