  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'arena-exits-meet-a-closed-street','juniper-city:major:arena-exits-meet-a-closed-street',205,1,'The Arena Exits Meet a Closed Street','A concert releases its crowd into a street that another permit has closed for overnight work. Arena staff hold the exits briefly and reopen a wider route before anyone is hurt.','A sold-out show at Juniper Civic Arena lets out while a nearby street crew is setting barriers for overnight paving. The event permit and work permit each show a valid plan, but together they narrow the exit route too far. Nia Brooks spots the crowd backing up and stops her live post from sending more people toward that corner. Mateo Alvarez helps arena staff hold one exit while Gabriel Ortiz calls the work supervisor to move the barriers.

The crowd clears through a second route without injury, and paving begins late. The permits were reviewed by different desks. The city must decide who checks overlapping street use before the next large event, and the arena owes patrons an explanation for the pause.','Everyone got out safely. How did the arena and work permits collide?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['citywide','major-incident']::text[],'{"contentDigest":"5fb294bd5484e4f675e6df700216833ed4d1c9d807992ea9324fe83714d942b3","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
