  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'a-city-without-change','juniper-city:major:a-city-without-change',212,1,'A City Without Change','A payment-network outage leaves many Juniper shops unable to accept cards or mobile payments for an afternoon. Cash queues grow; small businesses improvise without putting customers in debt by accident.','A regional payment processor fails just as Juniper’s lunch rush begins. Stores from Alder District to Riverside can open their registers but cannot authorize most cards. Javier Morales posts a limited menu he can safely serve on cash and existing tabs. Emma Callahan sets aside flower orders already paid for rather than selling them twice. Caleb Bennett keeps hotel guests from being asked to repay bookings that the system cannot yet verify.

The processor returns that evening. Most transactions reconcile, but some customers were charged after seeing a decline screen. Merchants need a shared way to correct those duplicates without publishing names, card details, or who needed a meal on trust.','Payments are back, but some declines became charges. How will the city’s shops make people whole?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['citywide','major-incident']::text[],'{"contentDigest":"c442312bc16ee77e2a2fa83890208cac34a1194944d6ee941b6593f08dc3964e","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
