  insert into public.together_world_pulse_templates (world_id,slug,repeat_identity,scheduling_rank,content_version,title,feed_summary,detail_body,group_message,event_type,location_id,primary_character_template_id,significance,selection_weight,cooldown_days,content_rating,facts,active,tags,metadata) values (v_world,'the-night-market-moves','juniper-city:major:the-night-market-moves',213,1,'The Night Market Moves in One Hour','A storm warning forces the Riverside night market off the open landing with an hour to spare. Vendors move into approved indoor spaces, but one public performance cannot fit anywhere without a new plan.','The Riverside night market is more than a shopping trip: vendors, musicians, and families plan a whole evening around it. A fast storm warning closes the exposed landing. Naomi Chen activates an indoor backup route, Camila Reyes helps food stalls move without breaking cold storage, and Zoe Bennett tries to rework a large dance performance for a room that cannot hold its original audience.

The market opens late under cover, and the storm crosses the river without injuries. The dance becomes a short streamed rehearsal rather than an unsafe full show. Vendors argue afterward about who received the best replacement space and whether the city’s backup plan was built for stalls but not performers.','The market still happened. Whose part of the night did the backup plan leave out?','colony_wide',v_location,v_primary,0.95,1,60,'standard',v_facts,true,array['citywide','major-incident']::text[],'{"contentDigest":"dbb39f0303ced01b45f42971ad2943995918bb290a24614e519df47ff38d1bfe","pulseTier":"major"}'::jsonb) on conflict (world_id,slug) do update set content_version = excluded.content_version,title = excluded.title,feed_summary = excluded.feed_summary,detail_body = excluded.detail_body,group_message = excluded.group_message,event_type = excluded.event_type,location_id = excluded.location_id,primary_character_template_id = excluded.primary_character_template_id,significance = excluded.significance,selection_weight = excluded.selection_weight,cooldown_days = excluded.cooldown_days,content_rating = excluded.content_rating,facts = excluded.facts,active = true,tags = excluded.tags,metadata = excluded.metadata,updated_at = now() returning id into v_template;
